int XML_SetElementTypePrefix(XML_Parser parser, ELEMENT_TYPE *elementType) {
  const XML_Char *name = elementType->name;
  size_t len = 0;
  const XML_Char *colon = NULL;

  while (name[len] != '\0') {
    if (name[len] == ':') {
      colon = &name[len];
      break;
    }
    len++;
  }

  if (colon == NULL)
    return 1; /* No prefix present; nothing to do. */

  if (len == 0)
    return 0; /* Prefix at start of name is invalid. */

  /* Copy the prefix to the memory pool */
  char *prefix = (char *)MALLOC(parser->m_pool, len + 1);
  if (!prefix)
    return 0;

  for (size_t i = 0; i < len; i++)
    prefix[i] = name[i];
  prefix[len] = '\0';

  /* Look up the prefix in the DTD */
  NAMEDATA *prefixEntry = (NAMEDATA *)HASH_LOOKUP(parser->dtd->prefixNames, prefix);
  if (!prefixEntry) {
    FREE(parser->m_pool, prefix);
    return 0;
  }

  /* Assign the prefix to the element type */
  elementType->prefix = prefixEntry;
  return 1;
}

int XML_SetElementTypePrefix(XML_Parser parser, ELEMENT_TYPE *elementType) {
  const XML_Char *name = elementType->name;
  size_t len = 0;
  const XML_Char *colon = 0;

  while (name[len] != 0) {
    if (name[len] == ':') {
      colon = &name[len];
      break;
    }
    ++len;
  }

  if (colon == 0)
    return 1;  /* No colon, no prefix to set */

  if (colon == name)
    return 0;  /* Colon is the first character, invalid */

  XML_Memory_Handling_Suite *mem = &parser->m_handler;
  XML_Prefix *prefix = 0;

  {
    size_t prefixLen = (size_t)(colon - name);
    const XML_Char *prefixName = name;
    XML_Hashtable *table = parser->m_dtd->prefixes;

    if (!table)
      return 0;

    prefix = (XML_Prefix *)XML_HashtableFind(table, prefixName);
    if (!prefix) {
      prefix = (XML_Prefix *)mem->malloc(mem->ctx, sizeof(XML_Prefix));
      if (!prefix)
        return 0;
      prefix->name = mem->strdup(prefixName, mem->ctx);
      if (!prefix->name) {
        mem->free(prefix, mem->ctx);
        return 0;
      }
      XML_HashtableAdd(table, prefixName, prefix);
    }
  }

  elementType->prefix = prefix;
  return 1;
}

int setElementTypePrefix(XML_Parser parser, ELEMENT_TYPE *elementType) {
  const XML_Char *name = elementType->name;
  size_t nameLen = 0;
  const XML_Char *colon = NULL;
  XML_Memory_Handling_Suite *mem = parser->mem;
  XML_Prefix *prefix;

  while (name[nameLen] != '\0') {
    if (name[nameLen] == ':') {
      colon = &name[nameLen];
      break;
    }
    nameLen++;
  }

  if (colon == NULL)
    return 1;

  char *prefixName = (char *)mem->alloc(mem->ctx, (nameLen + 1) * sizeof(XML_Char));
  if (!prefixName)
    return 0;

  for (size_t i = 0; i < nameLen; i++) {
    prefixName[i] = name[i];
  }
  prefixName[nameLen] = '\0';

  prefix = (XML_Prefix *)hashTableLookup(parser->prefixes, prefixName);
  if (!prefix) {
    mem->free(mem->ctx, prefixName);
    return 0;
  }

  elementType->prefix = prefix;
  return 1;
}

int setElementTypePrefix(XML_Parser parser, ELEMENT_TYPE *elementType) {
  XML_DTD *dtd = (XML_DTD *)parser->m_dtd;
  const ENCODING *enc = dtd->encoding;
  const XML_Char *name = (const XML_Char *)elementType->name;
  const XML_Char *colon = NULL;
  size_t len = 0;
  size_t prefixLen = 0;
  XML_Char *prefix = NULL;
  int result = 0;

  while (name[len] != 0) {
    if (name[len] == ':') {
      colon = &name[len];
      break;
    }
    len++;
  }

  if (colon == NULL)
    return 1; /* No prefix present, nothing to do */

  if ((prefix = (XML_Char *)MALLOC(len + 1)) == NULL)
    return 0; /* Memory allocation failed */

  for (size_t i = 0; i < len; ++i)
    prefix[i] = name[i];
  prefix[len] = 0;

  XML_Prefix *foundPrefix = (XML_Prefix *)lookupPrefix(dtd, prefix, len, 1);

  if (foundPrefix == NULL)
    goto cleanup;

  elementType->prefix = foundPrefix;
  result = 1;

cleanup:
  if (!result)
    FREE(prefix);
  return result;
}

int XML_SetElementTypePrefix(XML_Parser parser, ELEMENT_TYPE *elementType) {
  const XML_Char *name = elementType->name;
  int i;
  for (i = 0; name[i] != 0 && name[i] != ':'; i++) {
    if (!XmlAddName(parser->m_prefixMem, &name[i], 1))
      return 0;
  }

  if (name[i] == ':') {
    XML_Prefix *prefix;
    if (name[i + 1] == 0) {
      return 0; /* invalid name */
    }

    prefix = XmlLookupPrefix(parser->m_prefixTable, name, i);
    if (!prefix)
      return 0;

    elementType->prefix = prefix;
    parser->m_prefixMem->end -= i;
  } else {
    elementType->prefix = NULL;
    parser->m_prefixMem->end = 0;
  }

  return 1;
}
